import request from '@/utils/requests'

// 获取地址列表
export const getAddressList = () => {
  return request.get('/address/list')
}

// 获取默认收获地址Id
export const getDefaultAddressId = () => {
  return request({
    method: 'GET',
    url: '/address/defaultId'
  })
}

// 设置默认收获地址Id
export const setDefaultAddressId = (addressId) => {
  return request({
    method: 'POST',
    url: '/address/setDefault',
    data: {
      addressId
    }
  })
}

// 根据addressId获取收货地址详情
export const getDetailByAddressId = (addressId) => {
  // console.log('getDetailByAddressId-addressId', addressId)
  return request({
    method: 'GET',
    url: '/address/detail',
    params: {
      addressId: String(addressId)
    }
  })
}

// 获取获取省市区，用来添加地址
export const getAddAddressList = () => {
  return request({
    method: 'GET',
    url: '/region/tree'
  })
}

// 新增收货地址
export const addAddress = (name, phone, region, detail) => {
  return request({
    method: 'POST',
    url: '/address/add',
    data: {
      form: {
        name: String(name),
        phone: String(phone),
        region,
        detail
      }
    }
  })
}

// 删除收货地址
export const deleteAddress = (addressId) => {
  return request({
    method: 'POST',
    url: '/address/remove',
    data: {
      addressId
    }
  })
}

// 编辑收货地址
export const editAddress = (addressId, name, phone, region, detail) => {
  const data = {
    addressId: String(addressId),
    form: {
      name: String(name),
      phone: String(phone),
      region,
      detail
    }
  }
  // console.log('edit-data', data)
  return request({
    method: 'POST',
    url: '/address/edit',
    data
  })
}
